-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla endgame_rotations) y los 12_enemigos_hsr_*.sql.
--
-- Rotaciones del endgame de Honkai: Star Rail: la actual de cada modo y la
-- siguiente cuando ya esta en los datos del juego.
--   Memory of Chaos, Pura ficcion y Espejismo apocaliptico: con fechas.
--   Arbitraje atipico: los datos no traen calendario; es la mas reciente.
--
-- Cada piso guarda sus dos mitades con los elementos recomendados por el juego
-- y las oleadas de enemigos (ids de la tabla enemies), y cada rotacion sus
-- efectos (los generales y los que se eligen).
--
-- Fuente: datos del propio juego (TurnBasedGameData), textos oficiales en
-- espanol. Las fechas son del calendario del juego (hora del servidor).
--
-- Inserta lo que falte y actualiza lo que ya exista. Cuando cambie la rotacion
-- hay que volver a generar este archivo.
--
-- Generado el 2026-09-15.

insert into public.endgame_rotations (
  id, game_id, mode, name, status, begins_on, ends_on, effects, floors
)
values
  ('hsr-moc-1034', 'honkai-star-rail', 'memory-of-chaos', 'Tormenta arrasadora', 'actual', '2026-08-17', '2026-09-28', '[{"nombre":"Recuerdo turbulento","descripcion":"Al comenzar cada ciclo, un aliado al azar de la Vía de la Cacería o de la Erudición realiza una acción inmediatamente, y el daño que inflige aumenta en un 80% durante 1 turno(s).","tipo":"general"}]'::jsonb, '[{"piso":1,"nombre":"Tormenta arrasadora I","mitades":[{"elementos":["Cuántico"],"oleadas":[["hsr-enemy-4022010","hsr-enemy-4033010","hsr-enemy-4022010"],["hsr-enemy-4033010","hsr-enemy-8003030"]]},{"elementos":["Físico","Imaginario"],"oleadas":[["hsr-enemy-8012010","hsr-enemy-8013010","hsr-enemy-8012010"],["hsr-enemy-8013010","hsr-enemy-3003050"]]}]},{"piso":2,"nombre":"Tormenta arrasadora II","mitades":[{"elementos":["Físico","Fuego"],"oleadas":[["hsr-enemy-5012030","hsr-enemy-5013010","hsr-enemy-5012030"],["hsr-enemy-5013010","hsr-enemy-4053010"]]},{"elementos":["Hielo","Viento"],"oleadas":[["hsr-enemy-2022060","hsr-enemy-2023010","hsr-enemy-2022060"],["hsr-enemy-2023010","hsr-enemy-2023020"]]}]},{"piso":3,"nombre":"Tormenta arrasadora III","mitades":[{"elementos":["Fuego","Hielo"],"oleadas":[["hsr-enemy-1002020","hsr-enemy-1013010","hsr-enemy-1002020"],["hsr-enemy-1013010","hsr-enemy-4053020"]]},{"elementos":["Fuego"],"oleadas":[["hsr-enemy-3002020","hsr-enemy-3003010","hsr-enemy-3002020"],["hsr-enemy-3003010","hsr-enemy-8003040"]]}]},{"piso":4,"nombre":"Tormenta arrasadora IV","mitades":[{"elementos":["Viento"],"oleadas":[["hsr-enemy-2032020","hsr-enemy-2033010","hsr-enemy-2032020"],["hsr-enemy-2033010","hsr-enemy-2013010"]]},{"elementos":["Rayo","Imaginario"],"oleadas":[["hsr-enemy-1012030","hsr-enemy-1013020","hsr-enemy-1012030"],["hsr-enemy-1013020","hsr-enemy-3003030"]]}]},{"piso":5,"nombre":"Tormenta arrasadora V","mitades":[{"elementos":["Rayo","Viento"],"oleadas":[["hsr-enemy-4032040","hsr-enemy-4033020","hsr-enemy-4032040"],["hsr-enemy-4033020","hsr-enemy-8003040"]]},{"elementos":["F