ico","Fuego"],"oleadas":[["hsr-enemy-5013010","hsr-enemy-3003040"],["hsr-enemy-5024010"]]}]},{"piso":12,"nombre":"Tormenta arrasadora XII","mitades":[{"elementos":["Rayo","Cuántico"],"oleadas":[["hsr-enemy-3013010","hsr-enemy-1023020"],["hsr-enemy-3024020"]]},{"elementos":["Fuego","Imaginario"],"oleadas":[["hsr-enemy-5013040","hsr-enemy-5013070"],["hsr-enemy-5014020"]]}]}]'::jsonb),
  ('hsr-pf-2026', 'honkai-star-rail', 'pure-fiction', 'Génesis del dominio', 'actual', '2026-09-14', '2026-10-19', '[{"nombre":"Captando el Chiste","descripcion":"Cada vez que se obtiene Chiste, los aliados acumulan 2 pts. de valor de Coraje adicionales.","tipo":"general"},{"nombre":"Tregua momentánea","descripcion":"La etapa posee una habilidad de Exultación especial que, al entrar en el Momento Aha, inflige 15 veces Daño de Exultación Imaginario a enemigos al azar. Cuando cualquier objetivo elimina a un enemigo, se obtienen 1 punto(s) de Chiste.","tipo":"general"},{"nombre":"Coraje tumultuoso","descripcion":"Al entrar en Coraje tumultuoso, Aha obtiene de inmediato un turno adicional que cuenta como 20 puntos fijos de Chiste. En este turno no se consume Chiste y el daño que infligen las habilidades de Exultación equivale al 50% del daño original. Durante Coraje tumultuoso, el daño recibido por los enemigos aumenta en un 50% y la VEL del Momento Aha aumenta en 40 pts.","tipo":"general"},{"nombre":"Jolgorio","descripcion":"Durante Coraje tumultuoso, el daño de Exultación que reciben los enemigos aumenta en un 30% y la VEL del Momento Aha aumenta adicionalmente en 20 pts.","tipo":"elegible"},{"nombre":"Fantasía","descripcion":"Después de que un aliado lance el ATQ básico o la habilidad básica, obtiene 1 punto(s) de Chiste. Durante Coraje tumultuoso, el daño que infligen los aliados aumenta en un 50%.","tipo":"elegible"},{"nombre":"Manía enigmática","descripcion":"Después de que un mnemoduende aliado ataque, obtiene 2 punto(s) de Chiste. Durante Coraje tumultuoso, el daño que infligen los mnemoduendes aliados aumenta en un 50%.","tipo":"elegible"}]'::jsonb, '[{"piso":1,"nombre":"Génesis del dominio I","mitades":[{"elementos":["Físico","Hielo","Cuántico"],"oleadas":[["hsr-enemy-4012020","hsr-enemy-4022010","hsr-enemy-5012110","hsr-enemy-4012020","hsr-enemy-4022010"],["hsr-enemy-4013010"],["hsr-enemy-8003020"]]},{"elementos":["Físico","Fuego","Hielo"],"oleadas":[["hsr-enemy-4062010","hsr-enemy-5012100","hsr-enemy-5012110","hsr-enemy-4062010","hsr-enemy-5012100"],["hsr-enemy-3003020"],["hsr-enemy-4063010"]]}]},{"piso":2,"nombre":"Génesis del dominio II","mitades":[{"elementos":["Físico","Hielo","Rayo"],"oleadas":[["hsr-enemy-1012010","hsr-enemy-2012010","hsr-enemy-5012110","hsr-enemy-1012010","hsr-enemy-2012010"],["hsr-enemy-4033020"],["hsr-enemy-2023030"]]},{"elementos":["Físico","Viento","Cuántico"],"oleadas":[["hsr-enemy-1002040","hsr-enemy-8002010","hsr-enemy-5012110","hsr-enemy-1002040","hsr-enemy-8002010"],["hsr-enemy-8003010"],["hsr-enemy-8003030"]]}]},{"piso":3,"nombre":"Génesis del dominio III","mitades":[{"elementos":["Hielo","Rayo","Imaginario"],"oleadas":[["hsr-enemy-1012030","hsr-enemy-4012010","hsr-enemy-5012110","hsr-enemy-1012030","hsr-enemy-4012010"],["hsr-enemy-3013010"],["hsr-enemy-1013020"]]},{"elementos":["Físico","Viento","Imaginario"],"oleadas":[["hsr-enemy-2032020","hsr-enemy-2002030","hsr-enemy-5012110","hsr-enemy-2032020","hsr-enemy-2002030"],["hsr-enemy-4033010"],["hsr-enemy-8013010"]]}]},{"piso":4,"nombre":"Génesis del dominio IV","mitades":[{"elementos":["Cuántico","Imaginario"],"oleadas":[["hsr-enemy-5012010","hsr-enemy-4012010","hsr-enemy-5012110","hsr-enemy-5012010","hsr-enemy-4012010"],["hsr-enemy-4023010"],["hsr-enemy-8024011"]]},{"elementos":["Físico","Imaginario"],"oleadas":[["hsr-enemy-5012100","hsr-enemy-4062020","hsr-enemy-5012110","hsr-enemy-5012100","hsr-enemy-4062020"],["hsr-enemy-2013020"],["hsr-enemy-5024010"]]}]}]'::jsonb),
  ('hsr-as-3020', 'honkai-star-rail', 'apocalyptic-shadow', 'Lupino celestial', 'actual', '2026-08-31', '2026-10-05', '[{"nombre":"Quebradura lingüística","descripcion":"Cuando un aliado usa una habilidad definitiva para atacar a un enemigo, aplica Quebradura al objetivo. Se puede acumular hasta 6 veces. Al comenzar el turno del objetivo, o cuando el objetivo es eliminado, inflige una cantidad fija de daño al objetivo y a los objetivos adyacentes según las acumulaciones de Quebradura.","tipo":"general"},{"nombre":"Ascuas de la ruina","descripcion":"Cuando un enemigo con Salvaguardia firme es afectado con Ruptura de Debilidad, todos los aliados disipan los estados de Control y activan sus habilidades definitivas.\nEl daño de habilidad básica y el Daño de Exultación que reciben todos los enemigos aumentan en un 25% y un 15% respectivamente.","tipo":"general"},{"nombre":"Tierra de la fertilidad","descripcion":"El daño de habilidad básica y de habilidad definitiva que infligen todos los aliados aumenta en un 30%, y el daño de habilidad básica y de habilidad definitiva que inflige el primer personaje del equipo aumenta en un 30% adicional.","tipo":"elegible"},{"nombre":"Fuerza imparable","descripcion":"El daño que infligen los mnemoduendes ignora un 20% de la DEF del objetivo.","tipo":"elegible"},{"nombre":"Radiante de alegría","descripcion":"El Daño de Exultación que reciben todos los enemigos aumenta en un 30%. Cuando hay personajes de la Vía de la Exultación en el equipo aliado, la eficiencia de la Ruptura de Debilidad de todos los aliados aumenta en un 50%.","tipo":"elegible"},{"nombre":"Brillantez literaria","descripcion":"La RES a Viento y la RES a Rayo de todos los enemigos se reducen en un 40%.","tipo":"elegible"},{"nombre":"Vida pasada: Sombras del pasado","descripcion":"Cuando hay 3 o más mnemoduendes aliados en la batalla, el daño que infligen todos los aliados aumenta en un 60%.","tipo":"elegible"},{"nombre":"Infección ósea","descripcion":"Después de que un aliado inflija Daño con el tiempo al enemigo, recupera 1 pt(s). de energía. El Daño con el tiempo que infligen todos los aliados ignora un 40% de la RES a todos los tipos de los objetivos.","tipo":"elegible"},{"nombre":"Transformación espiritual","descripcion":"Cada vez que un aliado consume pts. de habilidad básica, el Daño CRIT de esta unidad aumenta en un 6%. Se puede acumular hasta 10 veces.","tipo":"elegible"},{"nombre":"Armado hasta los dientes","descripcion":"El Daño Físico que infligen todos los aliados aumenta en un 50% y la RES a Físico de todos los enemigos se reduce en un 20%.","tipo":"elegible"}]'::jsonb, '[{"piso":1,"nombre":"Lupino celestial: Dificultad 1","mitades":[{"elementos":["Físico","Fuego","Hielo","Cuántico"],"oleadas":[["hsr-enemy-2024016"]]},{"elementos":["Físico","Fuego","Rayo","Cuántico"],"oleadas":[["hsr-enemy-2035012"]]}]},{"piso":2,"nombre":"Lupino celestial: Dificultad 2","mitades":[{"elementos":["Físico","Fuego","Hielo","Cuántico"],"oleadas":[["hsr-enemy-2024016"]]},{"elementos":["Físico","Fuego","Rayo","Cuántico"],"oleadas":[["hsr-enemy-2035012"]]}]},{"piso":3,"nombre":"Lupino celestial: Dificultad 3","mitades":[{"elementos":["Físico","Fuego","Hielo","Cuántico"],"oleadas":[["hsr-enemy-2024016"]]},{"elementos":["Físico","Fuego","Rayo","Cuántico"],"oleadas":[["hsr-enemy-2035012"]]}]},{"piso":4,"nombre":"Lupino celestial: Dificultad 4","mitades":[{"elementos":["Físico","Fuego","Hielo","Cuántico"],"oleadas":[["hsr-enemy-2024016"]]},{"elementos":["Físico","Fuego","Rayo","Cuántico"],"oleadas":[["hsr-enemy-2035012"]]}]}]'::jsonb),
  ('hsr-aa-9', 'honkai-star-rail', 'anomaly-arbitration', 'Retorno de la Legión', 'reciente', null, null, '[{"nombre":"Risa maravillosa","descripcion":"La Exultación de todos los aliados aumenta en un 40% y la PEN de la RES a todos los tipos del Daño de Exultación infligido aumenta en un 20%. Este efecto se duplica al lanzar una habilidad de Exultación.","tipo":"elegible"},{"nombre":"Beso final","descripcion":"Al comenzar el turno de cualquier aliado, todos los aliados recuperan un 25% fijo de energía. Este efecto solo se activa 1 vez por batalla. El daño de habilidad básica y de habilidad definitiva que infligen todos los aliados aumenta en un 40%.","tipo":"elegible"},{"nombre":"Memoria de enjambre","descripcion":"Cuando hay 1/2/3/4 mnemoduendes aliados, el daño que infligen todos los aliados aumenta en un 20%/25%/30%/50%.","tipo":"elegible"}]'::jsonb, '[{"piso":1,"nombre":"Caballero I","mitades":[{"elementos":["Fuego","Cuántico"],"oleadas":[["hsr-enemy-8033020","hsr-enemy-8003040"],["hsr-enemy-8033020","hsr-enemy-1004010"]],"efectos":[{"nombre":"Determinación","descripcion":"La Firmeza de los enemigos no se puede reducir y el Daño de Ruptura que reciben se reduce en un 50%.","tipo":"general"},{"nombre":"Cota de escamas","descripcion":"Al inicio, los enemigos tienen 20 acumulaciones de este efecto. Cada acumulación reduce el daño recibido en un 2%. Cada vez que un enemigo recibe un ataque, pierde 1 acumulación. Las acumulaciones de este efecto se restablecen cuando el jefe enemigo cambia de fase.","tipo":"general"}]}]},{"piso":2,"nombre":"Caballero II","mitades":[{"elementos":["Imaginario"],"oleadas":[["hsr-enemy-5023010","hsr-enemy-5013010"],["hsr-enemy-5014010"]],"efectos":[{"nombre":"Interrupción de tendencia","descripcion":"Después de que un enemigo reciba un ataque de un aliado, el daño y el Daño CRIT que recibe se reducen en un 2% y un 4% respectivamente. Este efecto se puede acumular hasta 10 veces. Cuando el enemigo recibe un ataque adicional o termina el Momento Aha, pasan a perderse 5 acumulación(es) de este efecto.","tipo":"general"}]}]},{"piso":3,"nombre":"Caballero III","mitades":[{"elementos":["Hielo","Cuántico"],"oleadas":[["hsr-enemy-5013010","hsr-enemy-8003020"],["hsr-enemy-4034010"]],"efectos":[{"nombre":"Fuerza conjunta","descripcion":"El daño que reciben los enemigos se reduce en un 60%. Cuando hay más de 4 aliados presentes en el campo de batalla, este efecto se reduce en un 20% por cada objetivo adicional.","tipo":"general"}]}]},{"piso":4,"nombre":"Jaque al rey","mitades":[{"elementos":["Hielo","Rayo","Cuántico"],"oleadas":[["hsr-enemy-4035010"]],"efectos":[{"nombre":"Bebesangre","descripcion":"Los aliados pierden 500 PV al comienzo de su turno. Este efecto puede ser letal.","tipo":"general"},{"nombre":"Cota de escamas","descripcion":"Al inicio, los enemigos tienen 20 acumulaciones de este efecto. Cada acumulación reduce el daño recibido en un 2%. Cada vez que un enemigo recibe un ataque, pierde 1 acumulación. Las acumulaciones de este efecto se restablecen cuando el jefe enemigo cambia de fase.","tipo":"general"}]},{"dificil":true,"elementos":["Hielo","Rayo","Cuántico"],"oleadas":[["hsr-enemy-4035010"]],"efectos":[{"nombre":"Bebesangre+","descripcion":"Los aliados pierden 1000 PV al comienzo de su turno. Este efecto puede ser letal.","tipo":"general"},{"nombre":"Cota de escamas+","descripcion":"Al inicio, los enemigos tienen 20 acumulaciones de este efecto. Cada acumulación reduce el daño recibido en un 3%. Cada vez que un enemigo recibe un ataque, pierde 1 acumulación. Las acumulaciones de este efecto se restablecen cuando el jefe enemigo cambia de fase.","tipo":"general"}]}]}]'::jsonb)
on conflict (id) do update
  set game_id = excluded.game_id,
      mode = excluded.mode,
      name = excluded.name,
      status = excluded.status,
      begins_on = excluded.begins_on,
      ends_on = excluded.ends_on,
      effects = excluded.effects,
      floors = excluded.floors,
      updated_at = now();

-- Las rotaciones que ya no son la actual ni la siguiente dejan de ensenarse.
update public.endgame_rotations
set status = 'pasada', updated_at = now()
where game_id = 'honkai-star-rail'
  and id not in ('hsr-moc-1034', 'hsr-pf-2026', 'hsr-as-3020', 'hsr-aa-9');

-- Comprobacion
select mode, name, status, begins_on, ends_on, jsonb_array_length(floors) as pisos
from public.endgame_rotations
where game_id = 'honkai-star-rail' and status <> 'pasada'
order by mode, begins_on nulls first;
